/** <span> carrying an Ionicons glyph, coloured by `color` (default currentColor). */
export function icon(name, size = 20, color) {
  const g = GLYPHS[name];
  if (!g) return '';
  return `<svg class="ba-ion" viewBox="0 0 512 512" width="${size}" height="${size}"
    fill="${color || 'currentColor'}" aria-hidden="true">${g}</svg>`;
}
